def _models(s, z):
    p=s['panel_b']; h=lambda a: np.sign(a)*np.maximum(abs(a)-.35,0)**1.5
    wb=fit(D(h(p['u'])),p['v']); b=D(h(z))@wb
    p=s['panel_c']; u=p['u']; q=lambda a:a*np.roll(a,-1,axis=1)
