    for a in [zz[0],np.c_[zz[0],zz[1]],np.c_[zz[0],zz[2]],np.c_[zz[0],zz[1],zz[5]],np.c_[zz[0],zz[6],zz[7]]]:
        for aa in [a,np.arcsinh(a)]:
